window.SHOTS={"w": 1920, "h": 1080, "fps": 30, "duration": 657.09, "shots": [{"id": 1, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "stamp", "text": "LOSS", "at": 0.7, "x": 0.78, "y": 0.3, "small": 1}], "src": "s001"}, "vo": "Duniya ki sabse hyped AI company ka CEO tension mein hai.", "visual": "Glass office at night. Young exec in grey sweater (Sam-type) holds his head, red loss chart behind him. Slow push-in.", "asset": "HF", "t0": 0.0, "seg": 0, "kind": "narr", "t1": 3.886, "tr": "cut"}, {"id": 2, "tpl": "map", "p": {"mode": "world", "logo": "ChatGPT"}, "vo": "Kyunki uska ChatGPT ghar-ghar pahunch gaya...", "visual": "Map of the world, ChatGPT logo pins pop on houses in every country.", "asset": "CODE", "t0": 3.886, "seg": 0, "kind": "narr", "t1": 6.432, "tr": "whip"}, {"id": 3, "tpl": "map", "p": {"mode": "world", "logo": "ChatGPT", "freeze": 1, "stamp": "LOSS"}, "vo": "...phir bhi company loss mein ja rahi hai.", "visual": "Pins freeze; a red \"LOSS\" stamp slams on the CEO's desk.", "asset": "CODE", "t0": 6.432, "seg": 0, "kind": "narr", "t1": 8.574, "tr": "whip"}, {"id": 4, "tpl": "windows", "p": {"srcs": ["s004a", "s004b", "s004c"], "labels": ["USA", "EUROPE", "INDIA"]}, "vo": "(no VO, 3 s)", "visual": "Three windows open one by one: Window 1, a US garage team builds a startup with ChatGPT. Window 2, a European dev ships a website. Window 3, an Indian couple makes cute AI couple photos and giggles.", "asset": "HF x3", "t0": 8.574, "t1": 10.274, "tr": "whip"}, {"id": 5, "tpl": "title", "p": {"text": "AI ERA", "style": "neon", "sub": "WELCOME TO THE"}, "vo": "Welcome to the AI era...", "visual": "Windows zoom out into a neon \"AI ERA\" title card.", "asset": "CODE", "t0": 10.274, "seg": 0, "kind": "narr", "t1": 11.574, "tr": "whip"}, {"id": 6, "tpl": "balloon", "p": {"mode": "inflate", "counter": {"prefix": "$", "to": 7000000000000.0}, "label": "KA GAMBLE"}, "vo": "...jahan ek simple sa chatbot, dekhte-dekhte 7 trillion dollar ka gamble ban gaya.", "visual": "A tiny chat bubble inflates into a huge balloon; counter rolls $0 → $7,000,000,000,000. Balloon stretches tight.", "asset": "CODE", "t0": 11.574, "seg": 0, "kind": "narr", "t1": 15.35, "tr": "whip"}, {"id": 7, "tpl": "calendar", "p": {"wd": "WED", "day": 30, "month": "NOV", "year": 2022}, "vo": "30 November 2022. Budhwar ka din.", "visual": "Calendar page flips to WED, 30 NOV 2022.", "asset": "CODE", "t0": 15.35, "seg": 1, "kind": "narr", "t1": 18.397, "tr": "whip"}, {"id": 8, "tpl": "image", "p": {"kb": "r", "src": "s008"}, "vo": "Ek company mein sab normal chal raha tha.", "visual": "Wide shot of a lazy tech office, plants, laptops.", "asset": "HF", "t0": 18.397, "seg": 1, "kind": "narr", "t1": 20.513, "tr": "whip"}, {"id": 9, "tpl": "image", "p": {"cuts": [[0, 0.05, 0.36, 0.8], [0.3, 0.1, 0.4, 0.75], [0.62, 0.05, 0.38, 0.8]], "src": "s008"}, "vo": "Log coffee pi rahe the, memes share kar rahe the, developers bugs fix kar rahe the.", "visual": "Quick cuts on the same office: coffee sip, laughing at a phone meme, dev squashing a cartoon bug on screen.", "asset": "HF (1 image, 3 crops)", "t0": 20.513, "seg": 1, "kind": "narr", "t1": 25.307, "tr": "punch"}, {"id": 10, "tpl": "launch", "p": {"logo": "OpenAI", "title": "ChatGPT", "type": "Today we launched ChatGPT.", "time": "8:38 PM"}, "vo": "Aur usi din OpenAI ne apna chatbot drop kiya... ChatGPT.", "visual": "Screen glows; \"ChatGPT\" title drops in with OpenAI logo. Typewriter text: today we launched ChatGPT, 8:38 PM.", "asset": "CODE", "t0": 25.307, "seg": 1, "kind": "narr", "t1": 27.905, "tr": "whip"}, {"id": 11, "tpl": "tweet", "p": {"name": "Sam Altman", "handle": "@sama", "text": "today we launched ChatGPT. try talking with it here: chat.openai.com", "time": "30 Nov 2022"}, "vo": "(tweet)", "visual": "Sam Altman's launch tweet as a phone card.", "asset": "CODE", "t0": 27.905, "t1": 30.031, "tr": "whip"}, {"id": 12, "tpl": "notif", "p": {"clock": "24 HRS", "app": "ChatGPT"}, "vo": "24 ghante ke andar internet ko naya obsession mil gaya.", "visual": "Phone notifications explode, a \"24 HRS\" clock spins.", "asset": "CODE", "t0": 30.031, "seg": 1, "kind": "narr", "t1": 33.297, "tr": "whip"}, {"id": 13, "tpl": "image", "p": {"cuts": [[0, 0, 0.34, 1], [0.33, 0, 0.34, 1], [0.66, 0, 0.34, 1]], "src": "s013"}, "vo": "Koi email likhwa raha tha, koi code fix karwa raha tha, aur koi apni breakup story.", "visual": "Three split panels: office guy writing email, dev fixing code, a teen crying while typing a breakup story.", "asset": "HF", "t0": 33.297, "seg": 1, "kind": "narr", "t1": 38.03, "tr": "whip"}, {"id": 14, "tpl": "image", "p": {"kb": "in", "src": "s014"}, "vo": "SKIT — BETA (Gaurav): Papa, main ek AI bot se baat kar raha hoon... jo humein crorepati bana sakta hai!", "visual": "Living room sofa: Beta with laptop, excited; Papa with newspaper.", "asset": "HF", "t0": 38.03, "seg": 2, "kind": "skit", "t1": 42.8, "tr": "whip"}, {"id": 15, "tpl": "image", "p": {"crop": [0.48, 0.08, 0.52, 0.62], "kb": "in", "src": "s014"}, "vo": "PAPA (Amrut): Kaise?", "visual": "Papa lowers the newspaper, one eyebrow up.", "asset": "HF (same scene)", "t0": 42.8, "seg": 3, "kind": "skit", "t1": 43.9, "tr": "punch"}, {"id": 16, "tpl": "chat", "p": {"app": "ChatGPT", "type": "Mujhe 1 minute mein 100 crore ka business bana ke do. Profit 100% ho. Aur koi galti nahi honi chahiye.", "think": 1, "kw": "FACEPALM"}, "vo": "BETA typing: \"Mujhe 1 minute mein 100 crore ka business bana ke do. Profit 100% ho. Aur koi galti nahi honi chahiye.\"", "visual": "Laptop close-up, prompt types out letter by letter; ChatGPT \"thinking\" dots; Papa face-palms.", "asset": "CODE", "t0": 43.9, "seg": 4, "kind": "skit", "t1": 50.23, "tr": "whip"}, {"id": 17, "tpl": "counter", "p": {"to": 1000000, "indian": 1, "suffix": " USERS", "tag": "5 DAYS"}, "vo": "ChatGPT itna viral hua ki sirf 5 din mein 10 lakh users aa gaye.", "visual": "Counter 0 → 10,00,000 with \"5 DAYS\" tag.", "asset": "CODE", "t0": 50.23, "seg": 5, "kind": "narr", "t1": 54.608, "tr": "flash"}, {"id": 18, "tpl": "counter", "p": {"from": 1000000, "to": 100000000, "indian": 1, "suffix": " USERS", "tag": "2 MONTHS"}, "vo": "Aur 2 mahine mein 10 crore.", "visual": "Counter jumps to 10,00,00,000, \"2 MONTHS\".", "asset": "CODE", "t0": 54.608, "seg": 5, "kind": "narr", "t1": 56.743, "tr": "flash"}, {"id": 19, "tpl": "race", "p": {"title": "10 CRORE USERS TAK", "items": [["Instagram", 30, "2.5 YRS"], ["Facebook", 54, "4.5 YRS"]]}, "vo": "Instagram ko 10 crore users tak pahunchne mein dhai saal lage the. Facebook ko saadhe chaar saal.", "visual": "Race track: Instagram runner (2.5 yrs), Facebook runner (4.5 yrs) on a globe.", "asset": "CODE", "t0": 56.743, "seg": 5, "kind": "narr", "t1": 62.1, "tr": "whip"}, {"id": 20, "tpl": "race", "p": {"title": "10 CRORE USERS TAK", "items": [["Instagram", 30, "2.5 YRS"], ["Facebook", 54, "4.5 YRS"], ["ChatGPT", 2, "2 MONTHS"]], "win": "FASTEST EVER"}, "vo": "ChatGPT ban gaya... history ka sabse fast growing app.", "visual": "ChatGPT rocket zooms past both, \"FASTEST EVER\" trophy.", "asset": "CODE", "t0": 62.1, "seg": 5, "kind": "narr", "t1": 65.46, "tr": "whip"}, {"id": 21, "tpl": "image", "p": {"kb": "up", "ov": [{"k": "logo", "name": "Google", "rect": [0.405, 0.146, 0.295, 0.14]}, {"k": "alarm"}], "src": "s021"}, "vo": "Phir kya tha... Google ke headquarters mein full panic mode on ho gaya.", "visual": "Google HQ exterior, red alarm light spinning on the roof.", "asset": "HF", "t0": 65.46, "seg": 6, "kind": "narr", "t1": 69.38, "tr": "whip"}, {"id": 22, "tpl": "image", "p": {"kb": "in", "shake": 0.25, "src": "s022"}, "vo": "SKIT — BOSS (Amrut): Ye technology toh humari hai! Transformer model humne banaya tha! Uska kya hua?", "visual": "Boardroom: angry boss slams a \"Attention Is All You Need\" paper on the table; execs flinch.", "asset": "HF", "t0": 69.38, "seg": 7, "kind": "skit", "t1": 73.86, "tr": "whip"}, {"id": 23, "tpl": "image", "p": {"crop": [0.3, 0, 0.5, 0.62], "kb": "in", "ov": [{"k": "phone", "logo": "ChatGPT", "x": 0.3, "y": 0.5}], "src": "s022"}, "vo": "BOSS: Toh phir mera beta Google AI ki jagah ChatGPT kyun use kar raha hai?", "visual": "Boss holds up a phone showing ChatGPT.", "asset": "HF (same room)", "t0": 73.86, "seg": 8, "kind": "skit", "t1": 77.43, "tr": "punch"}, {"id": 24, "tpl": "image", "p": {"kb": "r", "src": "s024"}, "vo": "ENGINEER (Gaurav): Kyunki... hum ise launch karne se dar rahe the.", "visual": "Nervous engineer in hoodie, sweat drop, tiny voice.", "asset": "HF", "t0": 77.43, "seg": 9, "kind": "skit", "t1": 80.43, "tr": "whip"}, {"id": 25, "tpl": "image", "p": {"kb": "out", "ov": [{"k": "namecards", "items": ["Bard", "Gemini"]}], "src": "s022"}, "vo": "BOSS: Toh ab kuch bhi launch karo! Bard bolo, Gemini bolo, jo mann kare bolo. Bas launch karo!", "visual": "Boss points at the door; name cards \"Bard\" and \"Gemini\" fly across the table.", "asset": "HF + CODE", "t0": 80.43, "seg": 10, "kind": "skit", "t1": 85.27, "tr": "whip"}, {"id": 26, "tpl": "image", "p": {"kb": "l", "speed": 1, "ov": [{"k": "speedlines"}], "src": "s026"}, "vo": "Google full hustle mode mein aa gaya.", "visual": "Fast-forward office: people running, papers flying, speed lines.", "asset": "HF", "t0": 85.27, "seg": 11, "kind": "narr", "t1": 88.547, "tr": "whip"}, {"id": 27, "tpl": "image", "p": {"kb": "in", "src": "s027"}, "vo": "Technology uske Saalon se thi.", "visual": "Dusty vault opens, a glowing AI box sits inside covered in cobwebs.", "asset": "HF", "t0": 88.547, "seg": 11, "kind": "narr", "t1": 89.647, "tr": "whip"}, {"id": 28, "tpl": "cards", "p": {"style": "bubbles", "items": [["speech", "???"], ["gavel", "CASE"], ["paper", "MEDIA"]]}, "vo": "Par company dar rahi thi... ki AI kahin kuch galat na bol de, koi case na ho jaye, media mein naam kharab na ho jaye.", "visual": "Three worry bubbles pop over execs: speech bubble with \"???\", judge's gavel, newspaper headline.", "asset": "CODE", "t0": 89.647, "seg": 11, "kind": "narr", "t1": 96.132, "tr": "whip"}, {"id": 29, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "confetti"}], "src": "s029"}, "vo": "Aur OpenAI? Usne bina dare launch kar diya.", "visual": "OpenAI guy cuts a ribbon with giant scissors, confetti.", "asset": "HF", "t0": 96.132, "seg": 11, "kind": "narr", "t1": 98.969, "tr": "whip"}, {"id": 30, "tpl": "money", "p": {"from": "Microsoft", "to": "OpenAI", "bags": ["$10B", "$3B"]}, "vo": "Kuch hi hafton mein Microsoft ne OpenAI mein 10 billion dollar laga diye. Aur 3 billion dollar alag se ready rakhe.", "visual": "Microsoft logo truck dumps money bags \"$10B\" at OpenAI's door; a second \"$3B\" bag waits on the side.", "asset": "CODE", "t0": 98.969, "seg": 11, "kind": "narr", "t1": 105.495, "tr": "whip"}, {"id": 31, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "logo", "name": "Bard", "rect": [0.283, 0.155, 0.627, 0.615]}], "src": "s031"}, "vo": "Google ne jaldi-jaldi mein Bard launch kiya...", "visual": "Launch stage, Bard logo on screen, small crowd.", "asset": "HF", "t0": 105.495, "seg": 11, "kind": "narr", "t1": 107.94, "tr": "whip"}, {"id": 32, "tpl": "chat", "p": {"app": "Gemini", "msgs": [["me", "Gemini, ye batao duniya ka sabse popular insaan kaun hai?"]]}, "vo": "SKIT — USER (Gaurav): Gemini, ye batao duniya ka sabse popular insaan kaun hai?", "visual": "Phone chat UI, user types the question.", "asset": "CODE", "t0": 107.94, "seg": 12, "kind": "skit", "t1": 111.43, "tr": "whip"}, {"id": 33, "tpl": "chat", "p": {"app": "Gemini", "msgs": [["me", "Gemini, ye batao duniya ka sabse popular insaan kaun hai?"], ["bot", "Modi Ji."]], "old": 1}, "vo": "GEMINI (Devi): Modi Ji.", "visual": "Reply bubble appears.", "asset": "CODE", "t0": 111.43, "seg": 13, "kind": "skit", "t1": 112.53, "tr": "punch"}, {"id": 34, "tpl": "chat", "p": {"app": "Gemini", "msgs": [["me", "Modi Ji kaun?"], ["bot", "Modi sarkaar."]], "blank": 1}, "vo": "USER: Modi Ji kaun? / GEMINI: Modi sarkaar.", "visual": "Second Q and A bubbles; user's face goes blank.", "asset": "CODE + HF", "t0": 112.53, "seg": 14, "kind": "skit", "t1": 114.59, "tr": "whip"}, {"id": 35, "tpl": "image", "p": {"kb": "in", "shake": 0.3, "src": "s035"}, "vo": "Aur bas... pehle hi din Gemini ne poora raita phaila diya.", "visual": "A bowl of raita tips over the Google stage; audience gasps.", "asset": "HF", "t0": 114.59, "seg": 16, "kind": "narr", "t1": 118.02, "tr": "whip"}, {"id": 36, "tpl": "money", "p": {"from": "Amazon", "to": "Anthropic", "bags": ["$$$ BILLIONS"], "mode": "vault"}, "vo": "Doosri taraf, Amazon ne Anthropic mein billions lagane shuru kar diye.", "visual": "Amazon logo crane lowers a vault labelled \"$$$ BILLIONS\" next to an Anthropic logo building.", "asset": "CODE", "t0": 118.02, "seg": 17, "kind": "narr", "t1": 121.8, "tr": "whip"}, {"id": 37, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "VC — We fund AI", "rect": [0.77, 0.28, 0.065, 0.055]}], "src": "s037"}, "vo": "Aur investors ka scene ye tha...", "visual": "Door with sign \"VC — We fund AI\", camera pushes in.", "asset": "HF", "t0": 121.8, "seg": 17, "kind": "narr", "t1": 123.64, "tr": "whip"}, {"id": 38, "tpl": "image", "p": {"kb": "r", "ov": [{"k": "slide", "mode": "dogwalk", "rect": [0.285, 0.107, 0.475, 0.493]}], "src": "s038"}, "vo": "SKIT — STARTUP (Gaurav): Humara app kutton ko walk pe le jaata hai...", "visual": "Founder in hoodie with a dog on a leash and a slide \"DogWalk\".", "asset": "HF", "t0": 123.64, "seg": 18, "kind": "skit", "t1": 125.683, "tr": "whip"}, {"id": 39, "tpl": "image", "p": {"crop": [0.12, 0.02, 0.75, 0.75], "kb": "in", "ov": [{"k": "slide", "mode": "mlmap", "rect": [0.285, 0.107, 0.475, 0.493]}], "src": "s038"}, "vo": "...par best route chunne ke liye hum machine learning use karte hain.", "visual": "Slide changes to a map with a glowing \"ML\" route; the dog looks confused.", "asset": "HF + CODE", "t0": 125.683, "seg": 18, "kind": "skit", "t1": 128.9, "tr": "punch"}, {"id": 40, "tpl": "image", "p": {"kb": "in", "shake": 0.15, "ov": [{"k": "tag", "text": "$5 CRORE", "x": 0.2, "y": 0.7}], "src": "s040"}, "vo": "INVESTOR (Amrut): Chup! Ye lo 5 crore dollar.", "visual": "Investor in red tie throws a cheque, money rains.", "asset": "HF", "t0": 128.9, "seg": 19, "kind": "skit", "t1": 130.95, "tr": "whip"}, {"id": 41, "tpl": "image", "p": {"crop": [0.5, 0.15, 0.5, 0.7], "kb": "r", "flip": 1, "src": "s038"}, "vo": "STARTUP: Aap humara demo nahi dekhenge?", "visual": "Founder holds a laptop up; investor already walking off with a cigar.", "asset": "HF", "t0": 130.95, "seg": 20, "kind": "skit", "t1": 133.29, "tr": "whip"}, {"id": 42, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "tag", "text": "2023", "x": 0.08, "y": 0.12}], "src": "s042"}, "vo": "SKIT (2023) — PITCHER (Gaurav): Hum ek aisa app bana rahe hain jisse aap Voldemort se direct baat kar sakte ho... wo bhi Python mein.", "visual": "Y Combinator-style pitch room, \"2023\" tag. Slide: an original spooky dark wizard (hooded black robe, wand, glowing green eyes) chatting with Python code.", "asset": "HF", "t0": 133.29, "seg": 21, "kind": "skit", "t1": 138.39, "tr": "whip"}, {"id": 43, "tpl": "image", "p": {"kb": "out", "src": "s043"}, "vo": "YC DESK (Amrut): Next, please.", "visual": "Bored judge with a stamp, not even looking up.", "asset": "HF", "t0": 138.39, "seg": 22, "kind": "skit", "t1": 139.49, "tr": "whip"}, {"id": 44, "tpl": "title", "p": {"text": "AI", "style": "sparkle"}, "vo": "PITCHER: Isme hum AI use kar rahe hain.", "visual": "Pitcher clicks; slide flashes a huge \"AI\" in sparkles.", "asset": "CODE", "t0": 139.49, "seg": 23, "kind": "skit", "t1": 140.93, "tr": "whip"}, {"id": 45, "tpl": "image", "p": {"kb": "in", "shake": 0.3, "src": "s045"}, "vo": "YC DESK: AI? Sach mein? / PITCHER: Yes.", "visual": "Judge's eyes pop out, glasses fly off.", "asset": "HF", "t0": 140.93, "seg": 24, "kind": "skit", "t1": 143.3, "tr": "whip"}, {"id": 46, "tpl": "reveal", "p": {"text": "$100M", "label": "YE LO"}, "vo": "YC DESK: Ye lo 100 million dollar.", "visual": "Briefcase opens, \"$100M\" glows.", "asset": "CODE", "t0": 143.3, "seg": 26, "kind": "skit", "t1": 144.97, "tr": "flash"}, {"id": 47, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "tag", "text": "$30M", "x": 0.7, "y": 0.25}], "src": "s047"}, "vo": "Ek company ne toh aisa AI banane ke liye 3 crore dollar utha liye...", "visual": "Robot A in a tiny office counts money, \"$30M\" tag.", "asset": "HF", "t0": 144.97, "seg": 27, "kind": "narr", "t1": 148.845, "tr": "whip"}, {"id": 48, "tpl": "image", "p": {"kb": "l", "src": "s048"}, "vo": "...jiska kaam tha doosre AI ke answers ko naye naam se wapas de dena.", "visual": "Robot A copies a paper from Robot B, rubs out the name, writes its own, hands it back.", "asset": "HF", "t0": 148.845, "seg": 27, "kind": "narr", "t1": 155.61, "tr": "whip"}, {"id": 49, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "GPU — SOLD OUT", "rect": [0.53, 0.13, 0.245, 0.1], "col": "#8b1a1a", "chip": 0}], "src": "s049"}, "vo": "Par asli pagalpan tha... GPU ki shortage.", "visual": "Empty shop shelf with a \"GPU — SOLD OUT\" sign, flies buzzing.", "asset": "HF", "t0": 155.61, "seg": 28, "kind": "narr", "t1": 160.265, "tr": "whip"}, {"id": 50, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "tag", "text": "GPU > SONA > TEL", "x": 0.5, "y": 0.12}], "src": "s050"}, "vo": "Computer ki ye chhoti-chhoti chips achanak sone aur tel se bhi zyada valuable ban gayi.", "visual": "Scale: a GPU on one side outweighs a gold bar and an oil barrel.", "asset": "HF", "t0": 160.265, "seg": 28, "kind": "narr", "t1": 163.571, "tr": "whip"}, {"id": 51, "tpl": "podium", "p": {"logo": "NVIDIA"}, "vo": "Aur Nvidia duniya ki sabse valuable company ban gayi.", "visual": "Nvidia logo climbs a podium to #1, crown drops on it.", "asset": "CODE", "t0": 163.571, "seg": 28, "kind": "narr", "t1": 165.96, "tr": "whip"}, {"id": 52, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "tag", "text": "NVIDIA CEO", "x": 0.66, "y": 0.2}], "src": "s052"}, "vo": "Nvidia ke CEO Jensen Huang conferences mein leather jacket pehen ke aise aane lage... jaise koi rockstar ho.", "visual": "Stage with smoke and spotlights, generic cartoon CEO in a black leather jacket with an \"NVIDIA CEO\" label, holding a chip like a guitar, crowd with phones.", "asset": "HF", "t0": 165.96, "seg": 28, "kind": "narr", "t1": 170.615, "tr": "whip"}, {"id": 53, "tpl": "image", "p": {"kb": "out", "ov": [{"k": "tag", "text": "#1", "x": 0.8, "y": 0.2}], "src": "s053"}, "vo": "Aur ek tarah se... wo the bhi.", "visual": "Crowd cheers, \"#1\" foam fingers.", "asset": "HF (same)", "t0": 170.615, "seg": 28, "kind": "narr", "t1": 173.98, "tr": "whip"}, {"id": 54, "tpl": "gpu", "p": {"n": 1, "tag": "$3 / hr"}, "vo": "Ek high-end GPU ka kiraya tha lagbhag 3 dollar per ghanta.", "visual": "One GPU with a price tag \"$3 / hr\".", "asset": "CODE", "t0": 173.98, "seg": 28, "kind": "narr", "t1": 175.565, "tr": "whip"}, {"id": 55, "tpl": "gpu", "p": {"n": 1, "tag": "$3 / hr", "wiggle": 1, "kw": "SASTA?"}, "vo": "Sasta lag raha hai na?", "visual": "Narrator shrug emoji; tag wiggles.", "asset": "CODE", "t0": 175.565, "seg": 28, "kind": "narr", "t1": 176.665, "tr": "whip"}, {"id": 56, "tpl": "gpu", "p": {"n0": 1, "n": 48}, "vo": "Par startup ka kaam  ek GPU se  nahi hone wala tha,..", "visual": "GPUs multiply on screen into a grid.", "asset": "CODE", "t0": 176.665, "seg": 28, "kind": "narr", "t1": 179.929, "tr": "whip"}, {"id": 57, "tpl": "gpu", "p": {"n0": 48, "n": 500, "tag": "x500"}, "vo": "Sirf ek model train karne ke liye bhi ek chhota startup 500 chips kiraye pe le sakta hai.", "visual": "Grid fills to \"x500\".", "asset": "CODE", "t0": 179.929, "seg": 28, "kind": "narr", "t1": 184.838, "tr": "whip"}, {"id": 58, "tpl": "counter", "p": {"prefix": "$", "to": 1500, "suffix": " / hr", "style": "bill", "tag": "GPU RENT"}, "vo": "Yaani 1,500 dollar per ghanta.", "visual": "Bill counter: $1,500 / hr.", "asset": "CODE", "t0": 184.838, "seg": 28, "kind": "narr", "t1": 187.354, "tr": "flash"}, {"id": 59, "tpl": "counter", "p": {"prefix": "$", "from": 1500, "to": 36000, "suffix": " / day", "style": "bill", "tag": "GPU RENT"}, "vo": "36,000 dollar per din.", "visual": "Counter jumps: $36,000 / day.", "asset": "CODE", "t0": 187.354, "seg": 28, "kind": "narr", "t1": 189.292, "tr": "flash"}, {"id": 60, "tpl": "counter", "p": {"prefix": "$", "from": 36000, "to": 1100000, "suffix": "+ / month", "style": "bill", "tag": "SIRF GPU KIRAYA", "slam": 1, "src": "s060"}, "vo": "Aur mahine ke 11 lakh dollar se zyada. Sirf GPU ke kiraye mein.", "visual": "Counter slams to $1.1M+ / month; founder faints behind it.", "asset": "CODE + HF", "t0": 189.292, "seg": 28, "kind": "narr", "t1": 193.816, "tr": "flash"}, {"id": 61, "tpl": "image", "p": {"src": "s061"}, "vo": "Phir bhi companies GPU aise jama kar rahi thi... jaise duniya khatam hone wali ho aur log ration stock kar rahe hon.", "visual": "Bunker shelves stacked with GPU boxes next to atta sacks and Maggi; exec counting them.", "asset": "HF", "t0": 193.816, "seg": 28, "kind": "narr", "t1": 199.924, "tr": "whip"}, {"id": 62, "tpl": "image", "p": {"src": "s062"}, "vo": "Nvidia jitni speed se chips bana rahi thi, demand usse bhi fast thi.", "visual": "Factory belt spitting chips vs a queue of hands grabbing faster.", "asset": "HF", "t0": 199.924, "seg": 28, "kind": "narr", "t1": 203.914, "tr": "whip"}, {"id": 63, "tpl": "counter", "p": {"to": 12, "suffix": " MONTHS", "style": "token", "tag": "YOUR WAIT"}, "vo": "Ek time pe waiting list 12 mahine tak pahunch gayi.", "visual": "Token machine shows \"Your wait: 12 MONTHS\"; calendar pages fly.", "asset": "CODE", "t0": 203.914, "seg": 28, "kind": "narr", "t1": 206.794, "tr": "flash"}, {"id": 64, "tpl": "image", "p": {"src": "s064"}, "vo": "Black market shuru ho gaya.", "visual": "Dark alley, man in trench coat opens his coat lined with GPUs.", "asset": "HF", "t0": 206.794, "seg": 28, "kind": "narr", "t1": 208.155, "tr": "whip"}, {"id": 65, "tpl": "image", "p": {"src": "s065"}, "vo": "Log ye chips border paar smuggle karne lage.", "visual": "Border checkpoint at night, a truck of \"vegetables\" with GPUs peeking out.", "asset": "HF", "t0": 208.155, "seg": 28, "kind": "narr", "t1": 210.59, "tr": "whip"}, {"id": 66, "tpl": "stickers", "p": {"year": "2024", "text": "AI-POWERED"}, "vo": "2024 tak har cheez \"AI-powered\" ho chuki thi.", "visual": "\"2024\" title; a sticker \"AI-POWERED\" slaps onto random objects.", "asset": "CODE", "t0": 210.59, "seg": 29, "kind": "narr", "t1": 213.961, "tr": "flash"}, {"id": 67, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "tag", "text": "+10% EFFICIENCY", "x": 0.7, "y": 0.2}], "src": "s067"}, "vo": "Aapka toaster ab bread ko 10% zyada efficiently jala sakta tha.", "visual": "Toaster with an \"AI\" sticker pops out black, smoking toast; \"+10% EFFICIENCY\" badge.", "asset": "HF", "t0": 213.961, "seg": 29, "kind": "narr", "t1": 218.046, "tr": "whip"}, {"id": 68, "tpl": "calendar", "p": {"mode": "app", "text": "AI suggests: 3:00 AM meeting"}, "vo": "Aapka calendar app algorithm se meeting ka time suggest kar raha tha.", "visual": "Phone calendar shows \"AI suggests: 3:00 AM meeting\"; user groans.", "asset": "CODE", "t0": 218.046, "seg": 29, "kind": "narr", "t1": 221.6, "tr": "whip"}, {"id": 69, "tpl": "image", "p": {"src": "s069"}, "vo": "Aur supermarket ka self-checkout? Camera toh pehle bhi tha...", "visual": "Self-checkout with an old camera on top.", "asset": "HF", "t0": 221.6, "seg": 29, "kind": "narr", "t1": 224.771, "tr": "whip"}, {"id": 70, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "MACHINE LEARNING", "rect": [0.305, 0.075, 0.065, 0.09], "col": "#1d4ed8", "chip": 0}, {"k": "tag", "text": "MACHINE LEARNING", "x": 0.55, "y": 0.14, "at": 0.45}], "src": "s070"}, "vo": "...bas ab uska naam \"machine learning\" ho gaya tha.", "visual": "A worker sticks a new label \"MACHINE LEARNING\" over the same camera.", "asset": "HF (same)", "t0": 224.771, "seg": 29, "kind": "narr", "t1": 227.373, "tr": "whip"}, {"id": 71, "tpl": "image", "p": {"src": "s071"}, "vo": "Party full on thi.", "visual": "Rooftop party of execs, disco lights, AI balloons.", "asset": "HF", "t0": 227.373, "seg": 29, "kind": "narr", "t1": 228.58, "tr": "whip"}, {"id": 72, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "confetti", "cheques": 1}], "src": "s072"}, "vo": "Champagne khul rahi thi. Cheques clear ho rahe the.", "visual": "Champagne pops; a cheque printer spits cheques like confetti.", "asset": "HF + CODE", "t0": 228.58, "seg": 29, "kind": "narr", "t1": 231.456, "tr": "whip"}, {"id": 73, "tpl": "image", "p": {"freeze": 0.35, "sfx": ["scratch"], "src": "s073"}, "vo": "Phir kisi ne wo awkward sawaal pooch liya...", "visual": "Music cuts (SFX record scratch); everyone freezes mid-dance.", "asset": "HF (same)", "t0": 231.456, "seg": 29, "kind": "narr", "t1": 233.995, "tr": "whip"}, {"id": 74, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "spot"}], "src": "s074"}, "vo": "\"Bhai... ye sab chalane ka kharcha kitna aa raha hai?\"", "visual": "A small intern with a calculator raises his hand; spotlight on him.", "asset": "HF", "t0": 233.995, "seg": 29, "kind": "narr", "t1": 236.47, "tr": "whip"}, {"id": 75, "tpl": "calendar", "p": {"month": "JAN", "year": 2025}, "vo": "January 2025.", "visual": "Calendar flips to JAN 2025.", "asset": "CODE", "t0": 236.47, "seg": 30, "kind": "narr", "t1": 238.262, "tr": "whip"}, {"id": 76, "tpl": "tweet", "p": {"name": "Sam Altman", "handle": "@sama", "text": "OpenAI ke Pro subscription pe humein loss ho raha hai.", "meter": "BP"}, "vo": "Sam Altman ne ek aisa tweet kiya, jisne investors ka BP high kar diya.", "visual": "Phone card with the tweet; investor holding chest, BP meter needle into red.", "asset": "CODE + HF", "t0": 238.262, "seg": 30, "kind": "narr", "t1": 242.869, "tr": "whip"}, {"id": 77, "tpl": "tweet", "p": {"name": "Sam Altman", "handle": "@sama", "text": "OpenAI ke Pro subscription pe humein loss ho raha hai. Log ise humari expectation se kahin zyada use kar rahe hain.", "hl": 1}, "vo": "\"OpenAI ke Pro subscription pe humein loss ho raha hai. Log ise humari expectation se kahin zyada use kar rahe hain.\"", "visual": "Tweet text highlights word by word.", "asset": "CODE", "t0": 242.869, "seg": 30, "kind": "narr", "t1": 249.183, "tr": "whip"}, {"id": 78, "tpl": "title", "p": {"text": "YES, REALLY.", "style": "shake"}, "vo": "Haan, aapne sahi suna.", "visual": "Narrator text \"YES, REALLY.\" shakes.", "asset": "CODE", "t0": 249.183, "seg": 30, "kind": "narr", "t1": 250.902, "tr": "flash"}, {"id": 79, "tpl": "counter", "p": {"prefix": "$", "to": 200, "suffix": " / month", "style": "price", "tag": "PRO PLAN", "sub": "− LOSS PER USER"}, "vo": "OpenAI apne Pro plan ke 200 dollar mahina leta hai. Phir bhi har subscriber pe loss ho raha hai.", "visual": "Price card \"$200 / month\"; under it a red arrow \"- per user\".", "asset": "CODE", "t0": 250.902, "seg": 30, "kind": "narr", "t1": 257.031, "tr": "flash"}, {"id": 80, "tpl": "title", "p": {"text": "PAR RUKO...", "style": "tilt", "sfx": ["dundun"]}, "vo": "Par ruko... story aur kharab hoti hai.", "visual": "Screen tilts, dramatic zoom (SFX dun-dun).", "asset": "CODE", "t0": 257.031, "seg": 30, "kind": "narr", "t1": 259.417, "tr": "whip"}, {"id": 81, "tpl": "bars", "p": {"mode": "updown", "title": "OpenAI 2024", "items": [["REVENUE", 3.7, "$3.7B"], ["LOSS", -5, "$5B"]]}, "vo": "2024 mein OpenAI ka hisaab dekho. Revenue: 3.7 billion dollar. Loss: 5 billion dollar.", "visual": "Bar chart \"OpenAI 2024\": green bar $3.7B up, red bar $5B down, taller.", "asset": "CODE", "t0": 259.417, "seg": 30, "kind": "narr", "t1": 267.099, "tr": "flash"}, {"id": 82, "tpl": "image", "p": {"src": "s082"}, "vo": "Company sirf profit kamane mein fail nahi hui... jitna kamaya, usse zyada uda diya.", "visual": "Wallet with wings flying off, money trailing.", "asset": "HF", "t0": 267.099, "seg": 30, "kind": "narr", "t1": 272.089, "tr": "whip"}, {"id": 83, "tpl": "title", "p": {"text": "ASLI SHOCK", "style": "curtain"}, "vo": "Ab aata hai asli shocking part.", "visual": "Curtain opens.", "asset": "CODE", "t0": 272.089, "seg": 30, "kind": "narr", "t1": 274.031, "tr": "whip"}, {"id": 84, "tpl": "counter", "p": {"prefix": "$", "to": 6.7, "dec": 1, "suffix": " TRILLION", "tag": "BY 2030", "city": 1, "src": "s084"}, "vo": "Ek research firm ke hisaab se, 2030 tak AI aur uske data centers chalane ke liye 6.7 trillion dollar chahiye honge.", "visual": "Giant counter \"$6.7 TRILLION by 2030\" over a glowing data-centre city.", "asset": "HF + CODE", "t0": 274.031, "seg": 30, "kind": "narr", "t1": 282.18, "tr": "flash"}, {"id": 85, "tpl": "split", "p": {"mode": "block", "total": "$6.7T", "a": ["$5.2T", "AI INFRA", ["gpu", "chip", "bolt", "snow", "building"]], "b": ["$1.5T", "CLOUD", ["cloud"]], "hl": "a"}, "vo": "Ise thoda tod ke samjhte hain. 5.2 trillion dollar seedha AI ke infrastructure pe: GPU, chips, bijli, cooling aur data center banane pe.", "visual": "The $6.7T block splits: $5.2T chunk with icons (GPU, chip, bolt, snowflake, building).", "asset": "CODE", "t0": 282.18, "seg": 30, "kind": "narr", "t1": 291.824, "tr": "whip"}, {"id": 86, "tpl": "split", "p": {"mode": "block", "total": "$6.7T", "a": ["$5.2T", "AI INFRA", ["gpu", "chip", "bolt", "snow", "building"]], "b": ["$1.5T", "CLOUD", ["cloud"]], "hl": "b", "old": 1}, "vo": "Baaki 1.5 trillion dollar cloud infrastructure pe.", "visual": "Remaining $1.5T chunk with a cloud icon.", "asset": "CODE", "t0": 291.824, "seg": 30, "kind": "narr", "t1": 295.459, "tr": "punch"}, {"id": 87, "tpl": "logos", "p": {"items": ["Microsoft", "Google", "Amazon", "Meta"], "center": "$350B", "sub": "IN 2025"}, "vo": "Aur sirf chaar sabse badi tech companies se 2025 mein 350 billion dollar kharch karne ki ummeed thi. Ek saal mein.", "visual": "Four logo tiles (Microsoft, Google, Amazon, Meta) around \"$350B in 2025\".", "asset": "CODE", "t0": 295.459, "seg": 30, "kind": "narr", "t1": 303.322, "tr": "whip"}, {"id": 88, "tpl": "bars", "p": {"mode": "target", "items": [["NEEDED / YEAR", 2000, "$2T"]]}, "vo": "Is kharche ko justify karne ke liye AI companies ko 2030 tak har saal 2 trillion dollar kamane honge.", "visual": "Target bar \"$2T / year needed by 2030\".", "asset": "CODE", "t0": 303.322, "seg": 30, "kind": "narr", "t1": 309.955, "tr": "flash"}, {"id": 89, "tpl": "bars", "p": {"mode": "target", "items": [["NEEDED / YEAR", 2000, "$2T"], ["TODAY", 200, "$200B"]], "old": 1}, "vo": "Aur abhi poori AI industry ki total kamaai? Lagbhag 200 billion dollar.", "visual": "Tiny bar \"$200B today\" next to the huge target.", "asset": "CODE", "t0": 309.955, "seg": 30, "kind": "narr", "t1": 314.001, "tr": "flash"}, {"id": 90, "tpl": "bars", "p": {"mode": "target", "items": [["NEEDED / YEAR", 2000, "$2T"], ["TODAY", 200, "$200B"]], "old": 2, "arrow": "10x"}, "vo": "Yaani kamaai ko 10 guna karna hoga.", "visual": "\"10x\" arrow climbs between the bars.", "asset": "CODE", "t0": 314.001, "seg": 30, "kind": "narr", "t1": 316.34, "tr": "flash"}, {"id": 91, "tpl": "image", "p": {"src": "s091"}, "vo": "SKIT — BOARD MEMBER (Amrut): Sam, humare hisaab se 2025 mein revenue 20 billion dollar hoga. Aur tum keh rahe ho 2029 tak 100 billion kar doge?", "visual": "Boardroom: old board member with glasses holds a report; Sam-type exec in grey sweater at the whiteboard.", "asset": "HF", "t0": 316.34, "seg": 31, "kind": "skit", "t1": 325.06, "tr": "whip"}, {"id": 92, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "drawline"}], "src": "s092"}, "vo": "SAM (Gaurav): Humein isi speed se grow karna hoga.", "visual": "Sam proudly draws a line shooting straight up.", "asset": "HF + CODE", "t0": 325.06, "seg": 32, "kind": "skit", "t1": 327.04, "tr": "whip"}, {"id": 93, "tpl": "hockey", "p": {"mode": "morph"}, "vo": "BOARD MEMBER: Sam, ise speed nahi kehte. Ye toh aise insaan ka banaya hockey stick graph hai, jisne kabhi hockey kheli hi nahi.", "visual": "The drawn line morphs into a wobbly red hockey stick.", "asset": "CODE", "t0": 327.04, "seg": 33, "kind": "skit", "t1": 333.834, "tr": "whip"}, {"id": 94, "tpl": "counter", "p": {"prefix": "$", "to": 115, "suffix": "B", "tag": "CASH BURN TILL 2029", "fire": 1}, "vo": "BOARD MEMBER: Pata hai, sirf try karne mein kitna paisa lagega? / SAM: 2029 tak 115 billion dollar ka cash burn.", "visual": "Counter \"$115B burn\" with a match lighting money.", "asset": "CODE", "t0": 333.834, "seg": 33, "kind": "skit", "t1": 340.69, "tr": "flash"}, {"id": 95, "tpl": "calendar", "p": {"mode": "fast", "years": [2029, 2030, 2031]}, "vo": "BOARD MEMBER: Aur profit kab aayega? / SAM: 2029 mein. Shayad 2030 mein. Ya 2031?", "visual": "Sam flips calendar pages faster and faster.", "asset": "HF + CODE", "t0": 340.69, "seg": 35, "kind": "skit", "t1": 347.54, "tr": "whip"}, {"id": 96, "tpl": "hockey", "p": {"mode": "snap", "sfx": ["crack"]}, "vo": "BOARD MEMBER: Aur agar revenue 100 billion tak nahi pahuncha? Agar tumhari hockey stick toot gayi toh?", "visual": "Hockey stick snaps in two (SFX crack).", "asset": "CODE", "t0": 347.54, "seg": 37, "kind": "skit", "t1": 351.64, "tr": "whip"}, {"id": 97, "tpl": "image", "p": {"src": "s097"}, "vo": "SAM: Toh aur paisa raise kar lenge.", "visual": "Sam shrugs with a big smile.", "asset": "HF", "t0": 351.64, "seg": 38, "kind": "skit", "t1": 353.2, "tr": "whip"}, {"id": 98, "tpl": "image", "p": {"kb": "r", "ov": [{"k": "logo", "name": "Microsoft", "rect": [0.3, 0.07, 0.12, 0.06]}, {"k": "plaque", "text": "SAUDI", "rect": [0.545, 0.075, 0.13, 0.07], "chip": 0}, {"k": "plaque", "text": "PENSION FUND", "rect": [0.78, 0.08, 0.12, 0.055], "chip": 0}], "src": "s098"}, "vo": "BOARD MEMBER: Kisse? Bacha kaun hai? Microsoft? Saudi Arabia? Koi pension fund jo kuch zyada hi optimistic hai?", "visual": "Three doors behind him: Microsoft logo, desert palace, an old man with a \"PENSION\" cap and rose-tinted glasses.", "asset": "HF", "t0": 353.2, "seg": 39, "kind": "skit", "t1": 359.69, "tr": "whip"}, {"id": 99, "tpl": "image", "p": {"src": "s099"}, "vo": "SAM: Arre, duniya mein investors ki kami thodi hai!", "visual": "Sam winks, finger guns.", "asset": "HF", "t0": 359.69, "seg": 40, "kind": "skit", "t1": 362.37, "tr": "whip"}, {"id": 100, "tpl": "funnel", "p": {"from": "2021", "to": "AI"}, "vo": "2021 se private investors AI startups mein sainkdon billion dollar daal chuke hain.", "visual": "Money river flowing from a \"2021\" sign into an \"AI\" funnel.", "asset": "CODE", "t0": 362.37, "seg": 41, "kind": "narr", "t1": 367.385, "tr": "whip"}, {"id": 101, "tpl": "funnel", "p": {"from": "2021", "to": "AI", "balloons": 10, "label": "+$1 TRILLION"}, "vo": "Iska zyada hissa sirf 10 companies ko mila, jinki total value lagbhag 1 trillion dollar badh gayi.", "visual": "Funnel feeds 10 balloons that inflate; label \"+$1 TRILLION\".", "asset": "CODE", "t0": 367.385, "seg": 41, "kind": "narr", "t1": 373.088, "tr": "whip"}, {"id": 102, "tpl": "image", "p": {"src": "s102"}, "vo": "Har koi yahi bet laga raha tha... ki inmein se koi agla Google banega.", "visual": "Roulette wheel with 10 slots; investors betting chips.", "asset": "HF", "t0": 373.088, "seg": 41, "kind": "narr", "t1": 377.24, "tr": "whip"}, {"id": 103, "tpl": "title", "p": {"text": "GADBADIYAN", "style": "crack"}, "vo": "Phir gadbadiyan saamne aane lagi.", "visual": "Glass crack spreads across the screen.", "asset": "CODE", "t0": 377.24, "seg": 42, "kind": "narr", "t1": 379.049, "tr": "whip"}, {"id": 104, "tpl": "image", "p": {"src": "s104"}, "vo": "ChatGPT \"hallucinate\" karne laga.", "visual": "Robot with spiral eyes and a halo of stars.", "asset": "HF", "t0": 379.049, "seg": 42, "kind": "narr", "t1": 381.366, "tr": "whip"}, {"id": 105, "tpl": "image", "p": {"src": "s105"}, "vo": "Tech ki bhasha mein iska matlab hai... poore confidence ke saath kuch bhi bana ke bol dena.", "visual": "Robot in sunglasses presenting a slide of nonsense, chest out.", "asset": "HF", "t0": 381.366, "seg": 42, "kind": "narr", "t1": 385.719, "tr": "whip"}, {"id": 106, "tpl": "paper", "p": {"mode": "dust", "title": "Study, 2031"}, "vo": "Aise research papers ka reference, jo exist hi nahi karte.", "visual": "Paper titled \"Study, 2031\" fades to dust.", "asset": "CODE", "t0": 385.719, "seg": 42, "kind": "narr", "t1": 388.924, "tr": "whip"}, {"id": 107, "tpl": "image", "p": {"src": "s107"}, "vo": "Aise court cases, jo kabhi hue hi nahi.", "visual": "Lawyer reads a case file; the pages are blank.", "asset": "HF", "t0": 388.924, "seg": 42, "kind": "narr", "t1": 391.201, "tr": "whip"}, {"id": 108, "tpl": "image", "p": {"src": "s108"}, "vo": "Aur aise numbers, jo shayad kisi doosre planet se aaye the.", "visual": "A UFO beams a chart down to earth.", "asset": "HF", "t0": 391.201, "seg": 42, "kind": "narr", "t1": 394.529, "tr": "whip"}, {"id": 109, "tpl": "chat", "p": {"app": "Search", "msgs": [["me", "cheese not sticking to pizza"], ["bot", "Add 1/8 cup of non-toxic glue to the sauce."]]}, "vo": "Google ke AI ne ek user ko salah di ki pizza pe cheese chipkane ke liye usme glue daal do.", "visual": "Search UI answer \"Add 1/8 cup glue\"; cut to a chef pouring glue on pizza.", "asset": "CODE + HF", "t0": 394.529, "seg": 42, "kind": "narr", "t1": 399.829, "tr": "whip"}, {"id": 110, "tpl": "chat", "p": {"app": "Forum", "msgs": [["bot", "lol just use glue"]], "upvote": 1}, "vo": "Ye usne Reddit ke ek mazaak se seekha tha. Haan, sach mein.", "visual": "A Reddit-style comment card with \"lol use glue\" and an upvote arrow.", "asset": "CODE", "t0": 399.829, "seg": 42, "kind": "narr", "t1": 403.328, "tr": "whip"}, {"id": 111, "tpl": "image", "p": {"kb": "in", "shake": 0.2, "sfx": ["gavel"], "src": "s111"}, "vo": "Phir cases shuru hue.", "visual": "Judge's gavel slams (SFX).", "asset": "HF", "t0": 403.328, "seg": 42, "kind": "narr", "t1": 404.643, "tr": "whip"}, {"id": 112, "tpl": "image", "p": {"src": "s112"}, "vo": "Writers, artists, journalists... sabka ek hi sawaal tha: \"Kya tumne mere copyrighted kaam se apna AI train kiya hai?\"", "visual": "Angry crowd holding pens, brushes, mics and protest signs in front of an AI office.", "asset": "HF", "t0": 404.643, "seg": 42, "kind": "narr", "t1": 411.882, "tr": "whip"}, {"id": 113, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "bubble", "text": "umm... haan.", "x": 0.55, "y": 0.25}], "src": "s113"}, "vo": "Jawab? \"Umm... haan.\"", "visual": "AI rep sweating, tiny voice bubble \"umm... haan\".", "asset": "HF", "t0": 411.882, "seg": 42, "kind": "narr", "t1": 414.056, "tr": "whip"}, {"id": 114, "tpl": "split", "p": {"mode": "lawsuit", "pairs": [["The New York Times", "OpenAI"], ["Getty Images", "Stability AI"]]}, "vo": "The New York Times ne OpenAI pe case kiya. Getty Images ne Stability AI pe case kiya.", "visual": "Two lawsuit papers slap onto a table with each logo pair.", "asset": "CODE", "t0": 414.056, "seg": 42, "kind": "narr", "t1": 418.725, "tr": "whip"}, {"id": 115, "tpl": "image", "p": {"src": "s115"}, "vo": "Writers ne companies ko court mein ghaseeta. Artists ne baaki companies ko.", "visual": "Writers dragging a robot by the leg into court; artists dragging another.", "asset": "HF", "t0": 418.725, "seg": 42, "kind": "narr", "t1": 422.93, "tr": "whip"}, {"id": 116, "tpl": "image", "p": {"src": "s116"}, "vo": "SKIT — AI COMPANY (Gaurav): Humne chori nahi ki. Humne public data se AI train kiya hai.", "visual": "Courtroom: AI lawyer in suit, confident.", "asset": "HF", "t0": 422.93, "seg": 43, "kind": "skit", "t1": 427.22, "tr": "whip"}, {"id": 117, "tpl": "image", "p": {"kb": "r", "ov": [{"k": "plaque", "text": "THE INTERNET", "rect": [0.69, 0.24, 0.21, 0.12], "col": "#1a1a1a", "chip": 0}], "src": "s117"}, "vo": "ARTIST (Devi): Tumne bina permission poore internet ka data utha liya... aur usse paisa kamaya.", "visual": "Artist points at a truck labelled \"THE INTERNET\" being loaded.", "asset": "HF", "t0": 427.22, "seg": 44, "kind": "skit", "t1": 432.5, "tr": "whip"}, {"id": 118, "tpl": "image", "p": {"src": "s118"}, "vo": "AI COMPANY: Achha... aise bologe toh illegal hi lagega.", "visual": "AI lawyer slowly sinks into his chair.", "asset": "HF (same)", "t0": 432.5, "seg": 45, "kind": "skit", "t1": 436.08, "tr": "whip"}, {"id": 119, "tpl": "balloon", "p": {"mode": "crack", "sfx": ["hiss"]}, "vo": "2024 ke beech tak cracks dikhne lage the.", "visual": "AI balloon with small cracks, air hissing (SFX).", "asset": "CODE", "t0": 436.08, "seg": 46, "kind": "narr", "t1": 438.714, "tr": "whip"}, {"id": 120, "tpl": "split", "p": {"mode": "megaphone"}, "vo": "Hype bahut loud tha. Par numbers darawne the.", "visual": "Split: megaphone shouting \"AI!\" vs a dark spreadsheet with red numbers.", "asset": "CODE", "t0": 438.714, "seg": 46, "kind": "narr", "t1": 441.823, "tr": "whip"}, {"id": 121, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "mosquito"}], "sfx": ["buzz"], "src": "s121"}, "vo": "Aur ab sabke dimaag mein ek hi sawaal ghoom raha tha... bilkul waise, jaise raat ke 3 baje kaan ke paas machhar ghoomta hai:", "visual": "Dark bedroom, 3:00 AM clock, a mosquito circles a sleeping investor's ear (SFX buzz).", "asset": "HF", "t0": 441.823, "seg": 46, "kind": "narr", "t1": 447.581, "tr": "whip"}, {"id": 122, "tpl": "title", "p": {"text": "Ye bubble phootega kab?", "style": "black"}, "vo": "\"Ye bubble phootega kab?\"", "visual": "Black screen, white text: Ye bubble phootega kab?", "asset": "CODE", "t0": 447.581, "seg": 46, "kind": "narr", "t1": 448.69, "tr": "flash"}, {"id": 123, "tpl": "meter", "p": {"mode": "valuation"}, "vo": "Loss behisaab hai. Companies ki value reality se kahin zyada lagti hai.", "visual": "Two meters: \"LOSS\" maxed red, \"VALUATION\" balloon far above a small \"REALITY\" box.", "asset": "CODE", "t0": 448.69, "seg": 47, "kind": "narr", "t1": 451.693, "tr": "whip"}, {"id": 124, "tpl": "balloon", "p": {"mode": "hold", "browser": 1, "kw": "KYUN?"}, "vo": "Lekin ye bubble waise nahi phoot raha, jaise dot-com ka bubble phoota tha. Kyun?", "visual": "Old 1999 browser window shatters next to the intact AI balloon; \"KYUN?\"", "asset": "CODE", "t0": 451.693, "seg": 47, "kind": "narr", "t1": 458.112, "tr": "whip"}, {"id": 125, "tpl": "image", "p": {"src": "s125"}, "vo": "Kyunki ise phulane walon ki jeb duniya mein sabse gehri hai.", "visual": "A giant suit pocket, endless money falling into it.", "asset": "HF", "t0": 458.112, "seg": 47, "kind": "narr", "t1": 459.212, "tr": "whip"}, {"id": 126, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "REVENUE: $0", "rect": [0.71, 0.06, 0.24, 0.28], "col": "#b91c1c", "chip": 0}, {"k": "tag", "text": "1999", "x": 0.1, "y": 0.12}, {"k": "tag", "text": "17 FOOSBALL TABLES", "x": 0.35, "y": 0.9, "at": 0.55}], "src": "s126"}, "vo": "1999 mein startups ki kamaai zero hoti thi... aur office mein masti ke liye 17 foosball tables hoti thi.", "visual": "\"1999\" sepia office with rows of foosball tables, revenue board \"$0\".", "asset": "HF", "t0": 459.212, "seg": 47, "kind": "narr", "t1": 465.15, "tr": "whip"}, {"id": 127, "tpl": "image", "p": {"kb": "up", "ov": [{"k": "logorow", "items": ["Microsoft", "Google", "Amazon", "Meta"]}], "src": "s127"}, "vo": "Aaj AI bubble ko paisa dene wali badi tech companies sach mein kamaati hain. Bahut zyada.", "visual": "Today: shiny towers with Microsoft, Google, Amazon, Meta logos, money pouring out of windows.", "asset": "HF", "t0": 465.15, "seg": 47, "kind": "narr", "t1": 472.229, "tr": "whip"}, {"id": 128, "tpl": "image", "p": {"src": "s128"}, "vo": "Itna paisa ki agar wo chahein... toh poora desh khareed lein.", "visual": "Exec pulls a small globe-shaped country out of a shopping cart.", "asset": "HF", "t0": 472.229, "seg": 47, "kind": "narr", "t1": 475.174, "tr": "whip"}, {"id": 129, "tpl": "logos", "p": {"items": ["Microsoft"], "mode": "rain", "sub": "AZURE CLOUD"}, "vo": "Microsoft, Azure se billions kamata hai.", "visual": "Microsoft logo + Azure cloud raining money.", "asset": "CODE", "t0": 475.174, "seg": 47, "kind": "narr", "t1": 476.605, "tr": "whip"}, {"id": 130, "tpl": "logos", "p": {"items": ["Google"], "mode": "coins", "sub": "ADS"}, "vo": "Google, ads se billions kamata hai.", "visual": "Google logo, ad cards turning into coins.", "asset": "CODE", "t0": 476.605, "seg": 47, "kind": "narr", "t1": 479.105, "tr": "whip"}, {"id": 131, "tpl": "image", "p": {"src": "s131"}, "vo": "Meta aapko wahi meme dikha ke billions kamata hai... jo aapka cousin pehle hi WhatsApp pe bhej chuka hai.", "visual": "Phone shows the same meme twice: WhatsApp from cousin, then the feed; coins drop.", "asset": "HF + CODE", "t0": 479.105, "seg": 47, "kind": "narr", "t1": 486.418, "tr": "whip"}, {"id": 132, "tpl": "meter", "p": {"mode": "profit"}, "vo": "Ye badi companies AI mein isliye invest nahi kar rahi ki abhi isse profit ho raha hai.", "visual": "Profit meter at zero, crossed out.", "asset": "CODE", "t0": 486.418, "seg": 47, "kind": "narr", "t1": 490.878, "tr": "whip"}, {"id": 133, "tpl": "image", "p": {"src": "s133"}, "vo": "Wo isliye invest kar rahi hain... kyunki unhe darr hai ki kahin wo peeche na reh jayein.", "visual": "Execs running a race, all looking back nervously.", "asset": "HF", "t0": 490.878, "seg": 47, "kind": "narr", "t1": 495.19, "tr": "whip"}, {"id": 134, "tpl": "cards", "p": {"style": "morph", "items": [["phone", "iPhone moment?"], ["search", "Google moment?"], ["chip", "AI moment?"]]}, "vo": "Agar AI agla iPhone moment ban gaya toh? Agla Google moment?", "visual": "Flash of a phone and a search bar morphing into an AI chip.", "asset": "CODE", "t0": 495.19, "seg": 47, "kind": "narr", "t1": 498.979, "tr": "whip"}, {"id": 135, "tpl": "image", "p": {"src": "s135"}, "vo": "Agar ye wo pal hua, jab poori duniya raaton-raat badal jaati hai?", "visual": "Day-night swipe over a city that turns futuristic.", "asset": "HF", "t0": 498.979, "seg": 47, "kind": "narr", "t1": 502.615, "tr": "whip"}, {"id": 136, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "BlackBerry", "rect": [0.4, 0.065, 0.37, 0.11], "col": "#f5f5f5", "chip": 0}], "src": "s136"}, "vo": "Toh jis company ne speed kam ki... wo agli BlackBerry ban jayegi. Aur koi bhi BlackBerry nahi banna chahta.", "visual": "Exec in front of a falling chart with a \"BlackBerry\" sign; others back away.", "asset": "HF", "t0": 502.615, "seg": 47, "kind": "narr", "t1": 508.477, "tr": "whip"}, {"id": 137, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "headlogo", "heads": [[0.09, 0.39, 0.052, "Google"], [0.375, 0.375, 0.052, "Microsoft"], [0.68, 0.385, 0.052, "Meta"], [0.915, 0.4, 0.048, "Amazon"]]}], "src": "s137"}, "vo": "In badi tech companies ko poker ke aise players samjho, jo unlimited paisa leke table pe baithe hain.", "visual": "Poker table: four players with logo heads (Google, Microsoft, Meta, Amazon), endless chip towers.", "asset": "HF", "t0": 508.477, "seg": 47, "kind": "narr", "t1": 513.832, "tr": "whip"}, {"id": 138, "tpl": "image", "p": {"ov": [{"k": "headlogo", "heads": [[0.09, 0.39, 0.052, "Google"], [0.375, 0.375, 0.052, "Microsoft"], [0.68, 0.385, 0.052, "Meta"], [0.915, 0.4, 0.048, "Amazon"]]}, {"k": "spotmove", "n": 4}], "src": "s137"}, "vo": "Microsoft peeche hata, toh Google jeet jayega. Google peeche hata, toh Amazon jeet jayega. Amazon peeche hata, toh Meta jeet jayega.", "visual": "Spotlight moves player to player; each one glances at the next.", "asset": "HF (same) + CODE", "t0": 513.832, "seg": 47, "kind": "narr", "t1": 520.98, "tr": "punch"}, {"id": 139, "tpl": "image", "p": {"src": "s139"}, "vo": "Koi palak nahi jhapka raha. Koi fold nahi kar raha. Har koi bet badhata ja raha hai.", "visual": "Close-ups of unblinking eyes; chips pushed to the middle, the pile grows taller.", "asset": "HF", "t0": 520.98, "seg": 47, "kind": "narr", "t1": 525.69, "tr": "whip"}, {"id": 140, "tpl": "balloon", "p": {"mode": "hold", "needle": 1}, "vo": "Aur yahin se asli tough sawaal aata hai. Agar har koi kharch karta rahe... toh bubble phootega kaise?", "visual": "The AI balloon floats over the poker table; a needle hovers near it.", "asset": "CODE", "t0": 525.69, "seg": 48, "kind": "narr", "t1": 532.301, "tr": "whip"}, {"id": 141, "tpl": "image", "p": {"src": "s141"}, "vo": "Short answer hai: jab real duniya ka koi event sabko majboor kar de... ki ab dikhawa band karna padega.", "visual": "A hand pulls a curtain off a stage set, revealing cardboard props.", "asset": "HF", "t0": 532.301, "seg": 48, "kind": "narr", "t1": 538.857, "tr": "whip"}, {"id": 142, "tpl": "cards", "p": {"style": "fan", "items": [["1", "PAISA BAND"], ["2", "BADA FAIL"]]}, "vo": "History mein aise events aam taur pe teen tarah ke hote hain.", "visual": "Three numbered cards fan out. Card 3 visual: an original giant dinosaur monster stomps into the city at night, people running.", "asset": "CODE", "t0": 538.857, "seg": 48, "kind": "narr", "t1": 542.236, "tr": "whip"}, {"id": 143, "tpl": "cards", "p": {"style": "flip", "items": [["1", "PAISA BAND"], ["2", "BADA FAIL"]], "flip": 0}, "vo": "Pehla: achanak paisa milna band ho jaye.", "visual": "Card 1 flips: \"PAISA BAND\".", "asset": "CODE", "t0": 542.236, "seg": 48, "kind": "narr", "t1": 545.113, "tr": "whip"}, {"id": 144, "tpl": "paper", "p": {"mode": "site", "title": "www.startup1999.com"}, "vo": "Dot-com ka bubble isliye nahi phoota tha ki website banana koi bekaar idea tha.", "visual": "A 1999 website mock-up, perfectly fine, with a check mark.", "asset": "CODE", "t0": 545.113, "seg": 48, "kind": "narr", "t1": 549.465, "tr": "whip"}, {"id": 145, "tpl": "image", "p": {"src": "s145"}, "vo": "Wo isliye phoota kyunki paise ka nal band ho gaya.", "visual": "A money tap squeaks shut; last coin drips.", "asset": "HF", "t0": 549.465, "seg": 48, "kind": "narr", "t1": 552.598, "tr": "whip"}, {"id": 146, "tpl": "cards", "p": {"style": "icons", "items": [["rate", "INTEREST RATES ↑"], ["tag", "LOAN MEHENGA"], ["bag", "FUNDING GAYAB"]]}, "vo": "Interest rates badhe. Loan mehenga ho gaya. Funding gayab ho gayi.", "visual": "Three quick icons: % arrow up, loan tag price jumps, money bag vanishes in smoke.", "asset": "CODE", "t0": 552.598, "seg": 48, "kind": "narr", "t1": 556.213, "tr": "whip"}, {"id": 147, "tpl": "grid", "p": {"mode": "signs"}, "vo": "Aur hazaaron companies raaton-raat khatam ho gayi.", "visual": "Rows of startup office signs go dark one after another.", "asset": "CODE", "t0": 556.213, "seg": 48, "kind": "narr", "t1": 559.149, "tr": "whip"}, {"id": 148, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "BUDGET", "rect": [0.32, 0.585, 0.14, 0.05], "col": "#ffd23f", "chip": 0}, {"k": "tag", "text": "GAME OVER", "x": 0.5, "y": 0.5, "at": 0.7, "red": 1}], "src": "s148"}, "vo": "Agar aane wale time mein interest rates badhte hain aur badi tech companies apna budget tight kar deti hain... toh AI bubble ka game turant khatam.", "visual": "Exec tightens a belt labelled \"BUDGET\"; the balloon's air hose kinks; \"GAME OVER\" flashes.", "asset": "HF + CODE", "t0": 559.149, "seg": 48, "kind": "narr", "t1": 566.853, "tr": "whip"}, {"id": 149, "tpl": "cards", "p": {"style": "flip", "items": [["1", "PAISA BAND"], ["2", "BADA FAIL"]], "flip": 1}, "vo": "Doosra: koi bahut badi aur sharmnaak failure saamne aa jaye.", "visual": "Card 2 flips: \"BADA FAIL\".", "asset": "CODE", "t0": 566.853, "seg": 48, "kind": "narr", "t1": 571.012, "tr": "whip"}, {"id": 150, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "BADA FAIL", "rect": [0.56, 0.03, 0.39, 0.27], "col": "#d11", "chip": 0}], "src": "s150"}, "vo": "Har bubble ka ek aisa moment hota hai. Ek itna bada fail, jise dekh ke sab ghabra jaate hain.", "visual": "Crowd watching a giant screen, all mouths open.", "asset": "HF", "t0": 571.012, "seg": 48, "kind": "narr", "t1": 576.707, "tr": "whip"}, {"id": 151, "tpl": "paper", "p": {"mode": "earnings", "title": "Q4 1999 RESULTS"}, "vo": "Dot-com ke time company results ne ummeedein todi thi.", "visual": "1999 earnings sheet with a red arrow crashing.", "asset": "CODE", "t0": 576.707, "seg": 48, "kind": "narr", "t1": 579.757, "tr": "whip"}, {"id": 152, "tpl": "image", "p": {"kb": "l", "ov": [{"k": "plaque", "text": "LEHMAN BROTHERS", "rect": [0.54, 0.045, 0.33, 0.12], "col": "#222", "chip": 0}, {"k": "tag", "text": "2008", "x": 0.1, "y": 0.12}], "src": "s152"}, "vo": "2008 mein Lehman Brothers tha.", "visual": "Lehman Brothers building; employee walking out with a cardboard box.", "asset": "HF", "t0": 579.757, "seg": 48, "kind": "narr", "t1": 581.788, "tr": "whip"}, {"id": 153, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "plaque", "text": "FTX", "rect": [0.46, 0.06, 0.48, 0.24], "col": "#222", "chip": 0}], "src": "s153"}, "vo": "Crypto mein FTX tha.", "visual": "Crypto coins falling off a table, an \"FTX\" sign cracking.", "asset": "HF", "t0": 581.788, "seg": 48, "kind": "narr", "t1": 583.667, "tr": "whip"}, {"id": 154, "tpl": "image", "p": {"cuts": [[0, 0, 0.36, 1], [0.32, 0, 0.36, 1], [0.64, 0, 0.36, 1]], "ov": [{"k": "plaque", "text": "STOP", "rect": [0.84, 0.3, 0.1, 0.3], "col": "#fff", "chip": 0, "cut": 2}], "src": "s154"}, "vo": "AI ke case mein ye kisi badi lab ke bhaari loss ka khulasa ho sakta hai. Kisi naye model ka buri tarah fail launch ho sakta hai. Ya koi aisa case, jo sab kuch rok de.", "visual": "Three mini-scenes: a giant red loss report, a launch stage where the robot faceplants, a court \"STOP\" order on a data center.", "asset": "HF x3", "t0": 583.667, "seg": 48, "kind": "narr", "t1": 593.4, "tr": "whip"}, {"id": 155, "tpl": "map", "p": {"mode": "timeline"}, "vo": "Toh abhi hum kahan khade hain?", "visual": "A \"YOU ARE HERE\" map pin drops on a timeline from 2022 to now.", "asset": "CODE", "t0": 593.4, "seg": 49, "kind": "narr", "t1": 595.099, "tr": "whip"}, {"id": 156, "tpl": "image", "p": {"kb": "out", "ov": [{"k": "headlogo", "heads": [[0.09, 0.39, 0.052, "Google"], [0.375, 0.375, 0.052, "Microsoft"], [0.68, 0.385, 0.052, "Meta"], [0.915, 0.4, 0.048, "Amazon"]]}], "src": "s137"}, "vo": "Badi tech companies ab bhi kharch kar rahi hain.", "visual": "Poker table again, chips still flowing.", "asset": "HF (reuse 137)", "t0": 595.099, "seg": 49, "kind": "narr", "t1": 597.663, "tr": "whip"}, {"id": 157, "tpl": "meter", "p": {"mode": "seismo"}, "vo": "Kisi result ne abhi tak bhoochaal nahi machaya. FTX level ka koi scam saamne nahi aaya.", "visual": "Seismograph line flat; an empty \"SCAM\" frame.", "asset": "CODE", "t0": 597.663, "seg": 49, "kind": "narr", "t1": 603.226, "tr": "whip"}, {"id": 158, "tpl": "balloon", "p": {"mode": "crack", "thin": 1}, "vo": "Cracks dikh rahe hain... par itne bade nahi ki bharosa toot jaye.", "visual": "Close-up of the balloon: thin cracks, but holding.", "asset": "CODE", "t0": 603.226, "seg": 49, "kind": "narr", "t1": 606.961, "tr": "whip"}, {"id": 159, "tpl": "balloon", "p": {"mode": "notch"}, "vo": "Toh haan, ye bubble phoola hua hai. Haan, numbers pagal kar dene wale hain.", "visual": "Balloon inflates a notch with each \"haan\".", "asset": "CODE", "t0": 606.961, "seg": 49, "kind": "narr", "t1": 611.653, "tr": "whip"}, {"id": 160, "tpl": "balloon", "p": {"mode": "hold", "megaphones": 1}, "vo": "Lekin ye sirf hype aur shor ki wajah se nahi phootega.", "visual": "Megaphones shout at the balloon; it does not pop.", "asset": "CODE", "t0": 611.653, "seg": 49, "kind": "narr", "t1": 614.654, "tr": "whip"}, {"id": 161, "tpl": "image", "p": {"kb": "in", "ov": [{"k": "headlogo", "heads": [[0.13, 0.32, 0.045, "Google"], [0.53, 0.335, 0.045, "Microsoft"], [0.7, 0.355, 0.045, "Meta"], [0.885, 0.355, 0.045, "Amazon"]]}], "src": "s161"}, "vo": "Ye tab phootega, jab in giants mein se koi aakhirkar bolega... \"Theek hai. Ab bahut ho gaya.\"", "visual": "One poker player slowly lays his cards down (Devi or Amrut voice for the quote).", "asset": "HF", "t0": 614.654, "seg": 49, "kind": "narr", "t1": 620.378, "tr": "whip"}, {"id": 162, "tpl": "image", "p": {"kb": "up", "ov": [{"k": "plaque", "text": "AI", "rect": [0.43, 0.16, 0.14, 0.16], "col": "rgba(255,255,255,.85)", "chip": 0}], "src": "s162"}, "vo": "Tab tak bubble hawa mein tairta rahega.", "visual": "The balloon drifts up over a city skyline at dusk.", "asset": "HF", "t0": 620.378, "seg": 49, "kind": "narr", "t1": 622.889, "tr": "whip"}, {"id": 163, "tpl": "balloon", "p": {"mode": "tighten"}, "vo": "Hum abhi explosion wale point pe nahi hain. Hum us point pe hain jahan tension lagataar badh rahi hai.", "visual": "Camera holds on the balloon, which is now stretched tight.", "asset": "CODE", "t0": 622.889, "seg": 49, "kind": "narr", "t1": 628.773, "tr": "whip"}, {"id": 164, "tpl": "image", "p": {"src": "s164"}, "vo": "Cheekh nikalne se pehle andar kheenchi gayi saans.", "visual": "A character takes a deep breath, eyes wide.", "asset": "HF", "t0": 628.773, "seg": 49, "kind": "narr", "t1": 631.834, "tr": "whip"}, {"id": 165, "tpl": "image", "p": {"src": "s165"}, "vo": "Dor tootne se pehle ka khinchaav.", "visual": "A rope stretched between two hands, last threads snapping.", "asset": "HF", "t0": 631.834, "seg": 49, "kind": "narr", "t1": 634.061, "tr": "whip"}, {"id": 166, "tpl": "title", "p": {"text": "NEXT: SEASON FINALE", "style": "tv"}, "vo": "Season ke last episode se theek pehle wala episode.", "visual": "TV screen: \"NEXT: SEASON FINALE\", then cut to black.", "asset": "CODE", "t0": 634.061, "seg": 49, "kind": "narr", "t1": 637.09, "tr": "whip"}, {"id": 167, "tpl": "endscreen", "p": {}, "vo": "(end card)", "visual": "Subscribe end screen with two video slots.", "asset": "CODE", "t0": 637.09, "t1": 657.09, "tr": "whip"}]};
